import { NextResponse } from 'next/server';
import { createServiceClient } from '@/lib/supabase/server';
import { generateToken, hashToken } from '@/lib/deviceAuth';
import { validateBody } from '@/lib/validation';
import { enrollDeviceSchema } from '@/lib/apiSchemas';

// Exchanges a one-time enrollment token (generated by you via
// /api/admin/devices/create-enrollment and entered once during setup on
// the client's PC) for a permanent device token. The permanent token is
// returned exactly once, here — it's stored encrypted on the device
// (Electron's safeStorage) and never shown again. Not device-token-gated
// itself (the device doesn't have one yet); guarded instead by the
// enrollment token's own single-use, short-expiry nature, plus the tight
// rate limit applied to this route in middleware.ts.
export async function POST(request: Request) {
  const validated = await validateBody(request, enrollDeviceSchema);
  if ('error' in validated) return validated.error;
  const { enrollmentToken } = validated.data;

  const supabase = createServiceClient();
  const enrollmentHash = await hashToken(enrollmentToken);

  const { data: pending, error: lookupError } = await supabase
    .from('device_credentials')
    .select('id, device_id, enrollment_expires_at')
    .eq('enrollment_token_hash', enrollmentHash)
    .is('token_hash', null)
    .single();

  if (lookupError || !pending) {
    return NextResponse.json({ error: 'Invalid or already-used enrollment token.' }, { status: 401 });
  }
  if (!pending.enrollment_expires_at || new Date(pending.enrollment_expires_at) < new Date()) {
    return NextResponse.json({ error: 'Enrollment token has expired.' }, { status: 401 });
  }

  const deviceToken = generateToken();
  const deviceTokenHash = await hashToken(deviceToken);

  const { error: updateError } = await supabase
    .from('device_credentials')
    .update({
      token_hash: deviceTokenHash,
      enrollment_token_hash: null,
      enrollment_expires_at: null,
    })
    .eq('id', pending.id);

  if (updateError) {
    return NextResponse.json({ error: updateError.message }, { status: 500 });
  }

  return NextResponse.json({ deviceToken, deviceId: pending.device_id });
}
